// Abonelik, fatura ve harcama satırlarındaki marka logoları: eski Mel Capital'in kuralları
// (BRAND_RULES, GENERIC_ICONS) ve Simple Icons (CC0) simge yolları. Arayüzden bağımsızdır: hangi ada
// hangi görünümün düştüğünü söyler; çizimi lib/src/logos.dart yapar. Kurallar eski uygulamayla aynı
// sırada denenir (test/brands_test.dart eski uygulamanın kendi çıktısıyla karşılaştırır).

import 'util.dart';

/// Bir adın logosu: marka simgesi, marka renginde kısaltma, fatura türü simgesi ya da baş harfler.
sealed class BrandLook {
  const BrandLook();
}

/// Simple Icons simgesi; koyu markalar sıcak koyu zeminde açık renkle, açık markalar koyu renkle çizilir.
class BrandSvg extends BrandLook {
  const BrandSvg(this.key, this.bg, this.fg);
  final String key;
  final int bg;
  final int fg;
  String get path => kBrandIcons[key]!.$2;
}

/// Simgesi olmayan marka: marka renginde kısaltma ("D+", "tcell").
class BrandText extends BrandLook {
  const BrandText(this.text, this.bg, this.ink);
  final String text;
  final int bg;
  final int ink;
}

/// Markası bilinmeyen fatura ya da gider: türüne göre çizgi simgesi (doğalgaz alev, elektrik şimşek…).
class BrandGeneric extends BrandLook {
  const BrandGeneric(this.icon, this.color);
  final String icon;
  final int color;
  String get path => kLineIcons[icon]!;
}

/// Hiçbiri değilse: adın ilk iki harfi, ada göre seçilen renkte.
class BrandInitials extends BrandLook {
  const BrandInitials(this.text, this.bg);
  final String text;
  final int bg;
}

final List<RegExp> _brandRes = [for (final r in kBrandRules) RegExp(r.pattern)];
final List<RegExp> _genericRes = [for (final r in kGenericRules) RegExp(r.pattern)];

const int _darkBg = 0xFF2C2824;
const int _lightInk = 0xFFF3EEE6;
const int _darkInk = 0xFF141210;
const int _genericDefault = 0xFFE3BF7C;
const List<int> _initialColors = [0xFF8A5A8F, 0xFF3F6F8F, 0xFF8F6A2F, 0xFF3F7F5A, 0xFF6A5AA0, 0xFF9A4F45];

/// Bilinen bir markaysa logosu (simge ya da kısaltma), değilse null. Harcama satırları bunu kullanır:
/// markası bilinmeyen harcamada kategori simgesi kalır.
BrandLook? brandOf(String? name) {
  final s = brandKey(name);
  for (var i = 0; i < kBrandRules.length; i++) {
    if (!_brandRes[i].hasMatch(s)) continue;
    final r = kBrandRules[i];
    final icon = r.icon;
    if (icon == null) return BrandText(r.text, r.color, r.ink);
    final c = kBrandIcons[icon]!.$1;
    final lum = (0.299 * ((c >> 16) & 255) + 0.587 * ((c >> 8) & 255) + 0.114 * (c & 255)) / 255;
    if (lum < 0.28) return BrandSvg(icon, _darkBg, _lightInk);
    return BrandSvg(icon, c, lum > 0.7 ? _darkInk : 0xFFFFFFFF);
  }
  return null;
}

/// Abonelik, fatura ve gider satırlarının logosu: marka, yoksa fatura türü simgesi, yoksa baş harfler.
BrandLook brandLook(String? name) {
  final b = brandOf(name);
  if (b != null) return b;
  final s = brandKey(name);
  for (var i = 0; i < kGenericRules.length; i++) {
    if (_genericRes[i].hasMatch(s)) return BrandGeneric(kGenericRules[i].icon, kGenericRules[i].color ?? _genericDefault);
  }
  final raw = name ?? '';
  final letters = raw.replaceAll(RegExp(r'[^0-9A-Za-zÇĞİÖŞÜçğıöşü+]'), '');
  final text = letters.isEmpty ? '?' : letters.substring(0, letters.length < 2 ? letters.length : 2);
  var h = 0;
  for (final c in raw.codeUnits) {
    h = (h * 31 + c) % 4294967296;
  }
  return BrandInitials(text, _initialColors[h % 6]);
}

