/// Marka kuralı: ada ([brandKey]) uyan ilk kural seçilir. [icon] bir Simple Icons anahtarıdır;
/// simgesi olmayan markalar marka renginde ([color]) kısaltmayla ([text], yazı rengi [ink]) gösterilir.
class BrandRule {
  const BrandRule(this.pattern, {this.icon, this.color = 0, this.text = '', this.ink = 0xFFFFFFFF});
  final String pattern;
  final String? icon;
  final int color;
  final String text;
  final int ink;
}

